// Written by `flisk project`. A Claude Code hook (.claude/settings.json, PreToolUse) that stops an AI agent from editing
// the files Flisk generates. Flisk writes them again on `flisk up`, so an edit there is lost or blocks the start; the
// agent is told which file to change instead. The list matches cli/src/utils/generated-paths.ts in flisk-sh/flisk.
import { readFileSync } from "node:fs";
import path from "node:path";

/** The file to change instead when `rel` (relative to the project root, "/" separated) is generated by Flisk, else null. */
export function generatedSource(rel) {
  const parts = rel.split("/").filter(Boolean);
  if (!parts.length || parts[0] === "..") return null;
  const gen = parts.indexOf(".autogenerated");
  if (gen >= 0) return gen === 0 ? "service.json" : `${parts.slice(0, gen).join("/")}/service.json`;
  const p = parts.join("/");
  if (
    p.startsWith(".flisk/.flisk-out/") ||
    p === "shared-platform-engineering/docker-templates" ||
    p.startsWith("shared-platform-engineering/docker-templates/") ||
    p.startsWith("product_autogenerated_resource_manifests/") ||
    p.startsWith("product_autogenerated_services_list/") ||
    p === "Tiltfile" ||
    /^TILT_[^/]+\.star$/.test(p) ||
    p === ".tiltignore" ||
    p === "services/platform/database-management/docker-compose.yml"
  ) {
    return "the service.json files";
  }
  return null;
}

function main() {
  let input = {};
  try {
    input = JSON.parse(readFileSync(0, "utf-8") || "{}");
  } catch {
    return 0;
  }
  const file = input.tool_input?.file_path ?? input.tool_input?.notebook_path;
  if (typeof file !== "string" || !file) return 0;
  const root = process.env.CLAUDE_PROJECT_DIR || input.cwd || process.cwd();
  const rel = path.relative(root, path.resolve(root, file)).split(path.sep).join("/");
  const source = generatedSource(rel);
  if (!source) return 0;
  process.stderr.write(
    `${rel} is generated by Flisk, and flisk up writes it again, so this edit would be lost. ` +
      `Change ${source} (then run flisk up) or your own code instead. ` +
      `To see where a file comes from: flisk config explain ${rel}\n`,
  );
  return 2;
}

if (process.argv[1] && path.basename(process.argv[1]) === "flisk-generated-guard.mjs")
  process.exit(main());
